import{describe,it,expect}from"vitest";import{HERITAGE_ARC_DATA,TIMELINE_DATA,renderCityDetails,renderTimeline}from"../../frontend/heritage-arc-up/script.js";describe("UP Heritage Arc Explorer Logic",()=>{it("should contain complete dataset for Agra, Lucknow, and Varanasi",()=>{const e=Object.keys(HERITAGE_ARC_DATA);expect(e).toEqual(["agra","lucknow","varanasi"]),e.forEach(e=>{const t=HERITAGE_ARC_DATA[e];expect(t).toHaveProperty("id"),expect(t).toHaveProperty("name"),expect(t).toHaveProperty("tagline"),expect(t).toHaveProperty("themeColor"),expect(t).toHaveProperty("monuments"),expect(Array.isArray(t.monuments)).toBe(!0),expect(t.monuments.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(t.cultureFood)).toBe(!0)})}),it("should render detailed HTML markup for selected city",()=>{const e=renderCityDetails("agra");expect(e).toContain("Agra"),expect(e).toContain("Taj Mahal"),expect(e).toContain("Fatehpur Sikri");const t=renderCityDetails("lucknow");expect(t).toContain("Lucknow"),expect(t).toContain("Bara Imambara");const r=renderCityDetails("varanasi");expect(r).toContain("Varanasi"),expect(r).toContain("Kashi Vishwanath")}),it("should return empty string for invalid city key",()=>{expect(renderCityDetails("invalid-city")).toBe("")}),it("should render complete historical timeline data",()=>{expect(Array.isArray(TIMELINE_DATA)).toBe(!0),expect(TIMELINE_DATA.length).toBe(4);const e=renderTimeline();expect(e).toContain("Spiritual Origins in Kashi & Sarnath"),expect(e).toContain("Architectural Zenith in Agra"),expect(e).toContain("Cultural Flowering of Lucknow")})});